define("theme_chronolms/dashboard", ['core/ajax', 'core/str'], function(Ajax, Str) {
    'use strict';
    function animateRing(pct) {
        var ring = document.getElementById('progress-ring-fill');
        var val  = document.getElementById('dashboard-ring-value');
        if (!ring) return;
        var r = 58;
        var circ = 2 * Math.PI * r;
        ring.style.strokeDasharray = circ;
        var offset = circ - (pct / 100) * circ;
        ring.style.strokeDashoffset = circ;
        setTimeout(function() {
            ring.style.transition = 'stroke-dashoffset 1.2s cubic-bezier(0.4, 0, 0.2, 1)';
            ring.style.strokeDashoffset = offset;
        }, 150);
        if (val) {
            var curr = 0;
            var step = pct / 30;
            var timer = setInterval(function() {
                curr = Math.min(curr + step, pct);
                val.textContent = Math.round(curr) + '%';
                if (curr >= pct) clearInterval(timer);
            }, 40);
        }
    }
    function loadCompletionStats() {
        var ring = document.getElementById('progress-ring-fill');
        if (!ring) return;
        Ajax.call([{
            methodname: 'core_course_get_enrolled_courses_by_timeline_classification',
            args: { classification: 'all', limit: 0, offset: 0, sort: 'fullname' }
        }])[0].then(function(response) {
            var courses = response.courses || [];
            if (courses.length === 0) { animateRing(0); return; }
            var totalPct = 0;
            var completed = 0;
            var inProgress = 0;
            courses.forEach(function(c) {
                var p = c.progress !== null && c.progress !== undefined ? c.progress : 0;
                totalPct += p;
                if (p >= 100) completed++;
                else if (p > 0) inProgress++;
            });
            var avg = Math.round(totalPct / courses.length);
            animateRing(avg);
            var el = function(id, text) { var e = document.getElementById(id); if (e) e.textContent = text; };
            el('courses-inprogress-count', inProgress);
            el('courses-completed-count',  completed);
            el('courses-total-count',      courses.length);
        }).catch(function() { animateRing(0); });
    }
    function loadBadges() {
        var shelf = document.getElementById('dashboard-badge-shelf');
        if (!shelf) return;
        Ajax.call([{
            methodname: 'core_badges_get_user_badges',
            args: { userid: 0, courseid: 0, page: 0, perpage: 5, search: '', onlypublic: false }
        }])[0].then(function(response) {
            var badges = response.badges || [];
            if (badges.length === 0) return;
            shelf.innerHTML = '';
            badges.forEach(function(badge) {
                var div = document.createElement('a');
                div.className   = 'badge-item';
                div.href        = '/badges/badge.php?hash=' + badge.uniquehash;
                div.title       = badge.name;
                div.innerHTML   = '<div class="badge-icon-wrap"><img src="' + badge.imageurl + '" alt="' + badge.name + '" style="width:36px;height:36px;border-radius:50%;"></div><span class="badge-name">' + badge.name + '</span>';
                shelf.appendChild(div);
            });
        }).catch(function() {});
    }
    return {
        init: function() {
            loadCompletionStats();
            loadBadges();
        }
    };
});
